namespace fs=std::filesystem;
namespace st=biglybtc::storage;
namespace core=biglybtc::core;
namespace {
void need(bool yes,const char* why){if(!yes){throw std::runtime_error(why);}}
template<class T>T take(std::expected<T,st::Error>&& value){if(!value){throw std::runtime_error(value.error().message);}return std::move(*value);}
std::string b(std::string_view value){return std::to_string(value.size())+':'+std::string(value);}
core::Document document(std::string value){auto result=core::Document::parse(std::move(value),st::compatibleConfigLimits());need(result.has_value(),"Invalid generated dictionary");return std::move(*result);}
void set(core::Document& doc,std::string_view key,std::string value){need(doc.replaceValue(key,std::move(value)).has_value(),"Cannot edit generated dictionary");}
void write(const fs::path& path,std::string_view bytes){fs::create_directories(path.parent_path());std::ofstream file(path,std::ios::binary);file.write(bytes.data(),static_cast<std::streamsize>(bytes.size()));need(bool(file),"Cannot write generated fixture");}
std::string digest(std::string_view bytes,const EVP_MD* algorithm,bool hex){std::array<unsigned char,EVP_MAX_MD_SIZE> value{};unsigned size=0;need(EVP_Digest(bytes.data(),bytes.size(),value.data(),&size,algorithm,nullptr)==1,"Cannot hash generated bytes");if(!hex){return {reinterpret_cast<const char*>(value.data()),size};}constexpr char digits[]="0123456789abcdef";std::string result;for(unsigned i=0;i<size;++i){result+=digits[value[i]>>4];result+=digits[value[i]&15];}return result;}
std::string jsonQuoted(std::string_view value){std::string out="\"";constexpr char h[]="0123456789abcdef";for(unsigned char c:value){if(c=='\"'||c=='\\'){out+='\\';out+=static_cast<char>(c);}else if(c<32){out+="\\u00";out+=h[c>>4];out+=h[c&15];}else{out+=static_cast<char>(c);}}return out+'\"';}
struct Record{core::TorrentHash hash;std::string row,state;std::vector<fs::path> files;std::vector<std::string> contents;};
Record makeRecord(const fs::path& profile,const fs::path& save,const fs::path& archives,std::string name,bool multi,unsigned seed){
  Record out;std::string data(40003,'\0');for(std::size_t i=0;i<data.size();++i){data[i]=static_cast<char>((i*37+seed)%251);}out.contents=multi?std::vector<std::string>{data.substr(0,17001),"",data.substr(17001)}:std::vector<std::string>{data};
  std::string pieces;for(std::size_t i=0;i<data.size();i+=16384){pieces+=digest(std::string_view(data).substr(i,std::min<std::size_t>(16384,data.size()-i)),EVP_sha1(),false);}std::string info="d";
  if(multi){info+="5:filesl";const std::array<std::string,3> names{"first-α.bin","empty.bin","last-数据.bin"};for(std::size_t i=0;i<names.size();++i){info+="d6:lengthi"+std::to_string(out.contents[i].size())+"e4:pathl"+b(names[i])+"ee";out.files.push_back(save/name/names[i]);}info+='e';}else{info+="6:lengthi"+std::to_string(data.size())+'e';out.files.push_back(save/name);}
  info+="4:name"+b(name)+"12:piece lengthi16384e6:pieces"+b(pieces)+'e';auto hash=core::TorrentHash::parse(digest(info,EVP_sha1(),false));need(hash.has_value(),"Invalid generated hash");out.hash=*hash;
  auto metadata=document("d8:announce"+b("http://127.0.0.1:1/announce")+"4:info"+info+'e');auto attrs=document("de");std::string stores="l",priorities="l";for(std::size_t i=0;i<out.files.size();++i){stores+="1:L";priorities+="i-1e";write(out.files[i],out.contents[i]);}
  set(attrs,"storetypes",stores+'e');set(attrs,"opaque.state","li7e3:rawe");set(attrs,"resumecomplete","i2e");set(metadata,"attributes",attrs.serialize());set(metadata,"unknown.future.plugin","d4:keep3:rawe");auto resumeData=document("de");set(resumeData,"resume data",b(std::string(pieces.size()/20,'\1')));set(resumeData,"valid","i1e");set(resumeData,"blocks","de");auto resume=document("de");set(resume,"data",resumeData.serialize());set(metadata,"resume",resume.serialize());out.state=metadata.serialize();const auto archive=archives/(out.hash.hex()+".torrent");write(archive,out.state);write(profile/"active"/(out.hash.hex()+".dat"),out.state);
  auto row=document("de");set(row,"torrent",b(archive.string()));set(row,"torrent_hash",b(digest(info,EVP_sha1(),false)));set(row,"save_dir",b(save.string()));set(row,"save_file",b(name));set(row,"state","i70e");set(row,"forceStart","i0e");set(row,"position",seed==17?"i1e":"i2e");set(row,"downloaded","i40003e");set(row,"uploaded","i123e");set(row,"completedbytes","i40003e");set(row,"file_priorities",priorities+'e');set(row,"opaque.row","li5e3:rawe");out.row=row.serialize();return out;
}
}
int main(int argc,char** argv){try{
  need(argc==3||argc==4,"Usage: file_operations_driver OWNED_CASE_ROOT relocate|relink|removeKeep|removeDelete [single|multi]");const fs::path root(argv[1]);const std::string mode(argv[2]);const bool multi=argc==3||std::string_view(argv[3])=="multi";need(argc==3||multi||std::string_view(argv[3])=="single","Invalid geometry");need(root.parent_path()==fs::path("/tmp")&&root.filename().string().starts_with("biglybtc-fileops-handoff-")&&root.lexically_normal()==root,"Fresh owned /tmp/biglybtc-fileops-handoff-* case required");
  if(!fs::exists(root)){need(fs::create_directory(root),"Cannot create owned case");fs::permissions(root,fs::perms::owner_all);}struct stat rootInfo{};need(::lstat(root.c_str(),&rootInfo)==0&&S_ISDIR(rootInfo.st_mode)&&rootInfo.st_uid==::geteuid()&&(rootInfo.st_mode&077)==0&&fs::canonical(root)==root&&fs::is_empty(root),"Case root must be private, canonical, owned and empty");
  st::FileOperationKind kind;if(mode=="relocate"){kind=st::FileOperationKind::Relocate;}else if(mode=="relink"){kind=st::FileOperationKind::Relink;}else if(mode=="removeKeep"){kind=st::FileOperationKind::RemoveKeepData;}else{need(mode=="removeDelete","Invalid operation");kind=st::FileOperationKind::RemoveDeleteData;}
  const auto profile=root/"profile",source=root/"source",destination=root/"destination";fs::create_directories(destination);auto selected=makeRecord(profile,source,root/"archives",multi?"Bundle-数据":"file-α.bin",multi,17);auto survivor=makeRecord(profile,root/"survivor",root/"archives","survivor.bin",false,29);
  const auto rawHash=[](const core::TorrentHash& hash){const auto bytes=hash.bytes();return std::string(reinterpret_cast<const char*>(bytes.data()),bytes.size());};
  const auto inventory="d9:downloadsl"+selected.row+survivor.row+"e10:pause_datald4:hash"+b(rawHash(selected.hash))+"5:forcei0eed4:hash"+b(rawHash(survivor.hash))+"5:forcei0eee21:unknown.future.pluginli7e3:rawee";
  write(profile/"downloads.config",inventory);static_cast<void>(document(inventory));write(root/"before-downloads.config",inventory);write(root/"before-target.dat",selected.state);write(root/"before-survivor.dat",survivor.state);
  if(kind==st::FileOperationKind::Relink){for(std::size_t i=0;i<selected.files.size();++i){write(destination/selected.files[i].lexically_relative(source),selected.contents[i]);}}
  std::string receipt;
  {
    auto lease=take(st::ProfileLease::acquire(profile));auto plan=take(st::prepareFileOperation(lease,{selected.hash,kind,kind==st::FileOperationKind::Relocate||kind==st::FileOperationKind::Relink?std::optional<fs::path>(destination):std::nullopt}));
    const auto& preview=plan.preview();receipt="{\n\"schema\":1,\"mode\":"+jsonQuoted(mode)+",\"geometry\":"+jsonQuoted(multi?"multi":"single")+",\"profile\":"+jsonQuoted(profile.string())+",\"targetHash\":"+jsonQuoted(selected.hash.hex())+",\"survivorHash\":"+jsonQuoted(survivor.hash.hex())+",\"sourceRoot\":"+jsonQuoted(preview.sourceRoot.string())+",\"targetRoot\":"+jsonQuoted(preview.targetRoot.string())+",\"approvalScopeDigest\":"+jsonQuoted(preview.approvalScopeDigest)+",\"files\":[";
    for(std::size_t i=0;i<preview.files.size();++i){const auto& file=preview.files[i];const auto expected=root/"expected"/(std::to_string(file.index)+".bin");write(expected,selected.contents[file.index]);if(i){receipt+=',';}receipt+="{\"index\":"+std::to_string(file.index)+",\"source\":"+jsonQuoted(file.source.string())+",\"destination\":"+jsonQuoted(file.destination.string())+",\"bytes\":"+std::to_string(file.actualBytes)+",\"sha256\":"+jsonQuoted(digest(selected.contents[file.index],EVP_sha256(),true))+",\"expected\":"+jsonQuoted(expected.string())+",\"device\":"+jsonQuoted(std::to_string(file.device))+",\"inode\":"+jsonQuoted(std::to_string(file.inode))+'}';}
    auto confirmation=take(st::confirmFileOperation(plan,preview.approvalScopeDigest,true));const auto result=take(st::applyFileOperation(lease,std::move(plan),confirmation));need(!st::hasPendingFileOperation(lease),"Successful operation retained a journal");receipt+="],\"moved\":"+std::to_string(result.filesMoved)+",\"deleted\":"+std::to_string(result.filesDeleted)+"}\n";
  }
  write(root/"result.json",receipt);std::cout<<receipt;return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 2;}}
